const getHelpEntry = id => HELP_ENTRIES.find(e => e.id === id) || null;
const searchHelp = query => {
  const q = (query || '').trim().toLowerCase();
  if (!q) return HELP_ENTRIES;
  return HELP_ENTRIES.filter(e => e.title.toLowerCase().includes(q) || e.short.toLowerCase().includes(q) || e.category.toLowerCase().includes(q) || (e.keywords || []).some(k => k.toLowerCase().includes(q)));
};
const validateHelpRegistry = () => {
  const seen = new Set();
  const docsPathRe = /^\/[\w\-/]+$/;
  for (const e of HELP_ENTRIES) {
    if (!e.id || seen.has(e.id)) throw new Error("help: duplicate or missing id \"".concat(e.id, "\""));
    seen.add(e.id);
    if (!HELP_CATEGORIES.includes(e.category)) throw new Error("help: bad category \"".concat(e.category, "\" on \"").concat(e.id, "\""));
    if (!e.title || !e.short) throw new Error("help: missing title/short on \"".concat(e.id, "\""));
    if (!Array.isArray(e.howTo) || e.howTo.length === 0) throw new Error("help: empty howTo on \"".concat(e.id, "\""));
    if (e.docsPath && !docsPathRe.test(e.docsPath)) throw new Error("help: bad docsPath \"".concat(e.docsPath, "\" on \"").concat(e.id, "\""));
  }
  return true;
};


